var p = msg.payload;
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { p = null; }
}
if (!p || typeof p !== 'object') {
    msg.payload = { erro: 'payload nao e um objeto JSON valido', bruto: msg.payload, topic: msg.topic };
    return [null, msg];
}

var bancada = p.bancada;
if (typeof bancada !== 'string' || bancada.length === 0 || bancada.length > 32) {
    msg.payload = { erro: 'campo "bancada" ausente ou invalido', evento: p, topic: msg.topic };
    return [null, msg];
}

var quando = p.ts ? new Date(p.ts) : null;
if (!quando || isNaN(quando.getTime())) {
    msg.payload = { erro: 'campo "ts" ausente ou nao e uma data valida', evento: p, topic: msg.topic };
    return [null, msg];
}

var delta = Number(p.delta);
if (!Number.isFinite(delta) || delta !== 1) {
    // RF01: cada evento representa uma unica passagem valida.
    // Nao descartamos por isso -- so avisamos e gravamos como 1.
    node.warn('delta inesperado (' + p.delta + ') na bancada ' + bancada + '; gravando como 1');
    delta = 1;
}

var evtId = (typeof p.evt_id === 'string' && p.evt_id.length > 0) ? p.evt_id : null;
var origem = (typeof p.origem === 'string' && p.origem.length > 0) ? p.origem : null;
var totalTurno = Number.isFinite(Number(p.total_turno)) ? Math.trunc(Number(p.total_turno)) : null;
var totalHora = Number.isFinite(Number(p.total_hora)) ? Math.trunc(Number(p.total_hora)) : null;

// Ordem dos parametros == ordem dos $1..$7 na query do node "Gravar evento".
msg.params = [bancada, evtId, quando.toISOString(), delta, origem, totalTurno, totalHora];
return [msg, null];

var os = global.get('os');
var fs = global.get('fs');

if (!os || !fs) {
    node.error('functionGlobalContext.os/fs ausente -- confira node-red/settings.js');
    return null;
}

var load1 = os.loadavg()[0];
var totalMem = os.totalmem();
var freeMem = os.freemem();
var memPct = totalMem > 0 ? ((totalMem - freeMem) / totalMem) * 100 : null;

// thermal_zone0 e' um link simbolico (ex.: -> ../../devices/virtual/thermal/
// thermal_zone0); por isso o mount precisa ser o /sys inteiro (/host_sys),
// nao so /sys/class/thermal -- um subdiretorio so faz o link apontar pra
// fora do que foi montado (ENOENT). Tenta thermal_zone0..3: o indice do
// sensor de CPU varia entre modelos/kernels de Raspberry Pi.
var tempC = null;
var erros = [];
for (var i = 0; i < 4 && tempC === null; i++) {
    var caminho = '/host_sys/class/thermal/thermal_zone' + i + '/temp';
    try {
        var raw = fs.readFileSync(caminho, 'utf8');
        tempC = parseInt(raw.trim(), 10) / 1000;
    } catch (e) {
        erros.push(caminho + ': ' + e.message);
    }
}
if (tempC === null) {
    node.warn('Temperatura indisponivel em thermal_zone0..3: ' + erros.join(' | '));
}

msg.params = [load1, memPct, tempC];
return msg;

