var stats = flow.get('broker_stats') || {};
var value = Number(msg.payload);

if (msg.topic === '$SYS/broker/clients/connected') {
    stats.clientes = Number.isFinite(value) ? value : null;
} else if (msg.topic === '$SYS/broker/messages/received') {
    stats.mensagens = Number.isFinite(value) ? value : null;
} else if (msg.topic === '$SYS/broker/uptime') {
    // payload tipico: "12345 seconds"
    var match = /^(\d+)/.exec(String(msg.payload));
    stats.uptime = match ? Number(match[1]) : null;
}

flow.set('broker_stats', stats);
return null;

var stats = flow.get('broker_stats') || {};
msg.params = [
    typeof stats.clientes === 'number' ? stats.clientes : null,
    typeof stats.mensagens === 'number' ? stats.mensagens : null,
    typeof stats.uptime === 'number' ? stats.uptime : null
];
return msg;

